 useEffect(()=>{if(!keeperDialog)return;const timer=setTimeout(()=>setKeeperDialog(false),4200);return()=>clearTimeout(timer);},[keeperDialog,keeperLine]);
 useEffect(()=>{if(!smithDialog)return;const t=setTimeout(()=>setSmithDialog(false),4200);return()=>clearTimeout(t);},[smithDialog,smithLine]);
