 const touchStart=(e:React.PointerEvent)=>{if(!bootReady.current||!['menu','play'].includes(view)||campModal.current||forgeRef.current)return;if(e.pointerType==='mouse'){if(view==='menu'){camp.current.route=[];camp.current.target=campRenderer.current.unproject(e.clientX,e.clientY);goal.current='';}return;}e.currentTarget.setPointerCapture(e.pointerId);pointer.current={x:e.clientX,y:e.clientY};setStick({x:e.clientX,y:e.clientY,dx:0,dy:0});};
 const touchMove=(e:React.PointerEvent)=>{if(!pointer.current)return;let x=e.clientX-pointer.current.x,y=e.clientY-pointer.current.y;const l=Math.hypot(x,y);if(l>45){x=x/l*45;y=y/l*45;}input.current.x=x/45;input.current.y=y/45;setStick({...pointer.current,dx:x,dy:y});};
