  {shrinePanel&&view==='menu'&&<SanctuaryPanel key={shrinePanel} profile={profile} initial={shrinePanel} onClose={closeCampPanel} onOffer={buyShrine} onRitual={(id,state)=>{if(campModal.current==='sanctuary')shrineRitual.current={id,...state};}}/>}
